GRANT USAGE ON SCHEMA finfolk_rpc TO finfolk_api;
GRANT EXECUTE ON FUNCTION finfolk_rpc.actor_id(),finfolk_rpc.member_permitted(boolean),finfolk_rpc.member_profile(),finfolk_rpc.profile_save(jsonb),finfolk_rpc.checkin_record(text) TO finfolk_api;
END IF; END $$;
